/* orbit_search.c -- (see PROVENANCE.md) cyclic Goethals-Seidel quadruples (A,B,C,D) of odd length n with
 * A skew and every block a union of orbits of a multiplier group H (H is
 * generated by the units given on the command line, -1 not in H).  B, C, D
 * are arbitrary H-invariant blocks.  Exhaustive within that ansatz.
 *
 * Reductions, all lossless:
 *   - B, C, D are taken with x[0] = +1 (negating a block keeps its PAF);
 *   - every block must have PSD(k) <= 4n (B, C, D: <= 4n-1, as PSD_A >= 1);
 *   - row sums: 1 + b^2 + c^2 + d^2 = 4n;
 *   - {B,C,D} is unordered: per row-sum multiset one value is designated
 *     as B's, and when C and D share a class only index pairs i <= j run.
 * Meet in the middle: (A,B) pairs in a hash table, (C,D) pairs probe it, keyed
 * on a 64-bit linear hash of the reduced PAF vector; every hash hit is
 * re-verified with integer PAF over all shifts 1..n-1.  Memory is bounded by
 * splitting on the low q bits of the hash.
 *
 * usage: orbit_search <out.txt> <maxpairs> <n> <t1> [t2 ...]     env CAP = solutions written, STOPAT = stop after this many
 * build: gcc -O3 -march=native -o orbit_search orbit_search.c -lm
 * A row-sum decomposition whose pair count exceeds maxpairs is skipped and counted in the RESULT line.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#define MAXN 257
static int n, K, m;
static int oid[MAXN], cls[MAXN], rep[MAXN];
static double Cc[MAXN][MAXN];
static uint64_t rnd[MAXN], target;
static long cap=200, stopat=1000000; static volatile int stopped=0;
static uint64_t splitmix(uint64_t *s){uint64_t z=(*s+=0x9e3779b97f4a7c15ULL);z=(z^(z>>30))*0xbf58476d1ce4e5b9ULL;z=(z^(z>>27))*0x94d049bb133111ebULL;return z^(z>>31);}

static void expand(uint32_t mask, signed char *x){ x[0]=1; for(int j=1;j<n;j++) x[j]=(mask>>oid[j])&1?1:-1; }
static void pafvec(const signed char *x, int *v){
    for(int r=0;r<m;r++){int s=rep[r],p=0; for(int j=0;j<n;j++){int k=j+s; if(k>=n)k-=n; p+=x[j]*x[k];} v[r]=p;}
}
static uint64_t hashv(const int *v){ uint64_t h=0; for(int r=0;r<m;r++) h+=rnd[r]*(uint64_t)(int64_t)((v[r]-n)/4); return h; }
static int psd_ok(const int *v, double lim){
    for(int k=0;k<m;k++){ double p=n; for(int r=0;r<m;r++) p+=v[r]*Cc[k][r]; if(p>lim+1e-6) return 0; }
    return 1;
}
typedef struct { size_t cnt, cap; uint32_t *mask; uint64_t *h; size_t *bst; } list_t;
static void push(list_t *L, uint32_t mask, uint64_t h){
    if(L->cnt==L->cap){ L->cap=L->cap?2*L->cap:1024; L->mask=realloc(L->mask,L->cap*4); L->h=realloc(L->h,L->cap*8); }
    L->mask[L->cnt]=mask; L->h[L->cnt]=h; L->cnt++;
}
static void bucket(list_t *L, int q){
    size_t P=(size_t)1<<q, msk=P-1; free(L->bst); L->bst=calloc(P+1,sizeof(size_t));
    for(size_t i=0;i<L->cnt;i++) L->bst[(L->h[i]&msk)+1]++;
    for(size_t p=0;p<P;p++) L->bst[p+1]+=L->bst[p];
    uint32_t *nm=malloc((L->cnt+1)*4); uint64_t *nh=malloc((L->cnt+1)*8); size_t *pos=malloc(P*sizeof(size_t));
    memcpy(pos,L->bst,P*sizeof(size_t));
    for(size_t i=0;i<L->cnt;i++){ size_t d=pos[L->h[i]&msk]++; nm[d]=L->mask[i]; nh[d]=L->h[i]; }
    free(L->mask); free(L->h); free(pos); L->mask=nm; L->h=nh; L->cap=L->cnt+1;
}
static int verify(uint32_t a,uint32_t b,uint32_t c,uint32_t d,FILE *out,long found){
    signed char x[4][MAXN]; uint32_t mk[4]={a,b,c,d};
    for(int i=0;i<4;i++) expand(mk[i],x[i]);
    for(int j=1;j<n;j++) if(x[0][j]!=-x[0][n-j]) return 0;
    /* blocks are H-invariant by construction, so PAF is constant on shift
       classes: counting checks one shift per class, written solutions all */
    for(int r=0;r<m;r++){ int s=rep[r],p=0; for(int i=0;i<4;i++) for(int j=0;j<n;j++) p+=x[i][j]*x[i][(j+s)%n]; if(p) return 0; }
    if(found<cap){
        for(int s=1;s<n;s++){ int p=0; for(int i=0;i<4;i++) for(int j=0;j<n;j++) p+=x[i][j]*x[i][(j+s)%n]; if(p){fprintf(stderr,"class check passed but full check failed\n");exit(4);} } for(int i=0;i<4;i++){ for(int j=0;j<n;j++) fputc(x[i][j]>0?'+':'-',out); fputc(i<3?' ':'\n',out);} fflush(out); }
    return 1;
}
int main(int argc,char **argv){
    if(argc<5){fprintf(stderr,"usage: %s <out.txt> <maxpairs> <n> <t1> [t2 ...]\n",argv[0]);return 2;}
    FILE *out=fopen(argv[1],"a"); double maxpairs=atof(argv[2]); n=atoi(argv[3]);
    int ng=argc-4, gens[16]; for(int i=0;i<ng;i++) gens[i]=atoi(argv[4+i]);
    if(!out||n<3||n>=MAXN||n%2==0) return 2;
    if(getenv("CAP")) cap=atol(getenv("CAP"));
    const char *aonly=getenv("AONLY"); if(aonly&&(int)strlen(aonly)!=n) return 2;
    if(getenv("STOPAT")) stopat=atol(getenv("STOPAT"));
    uint64_t seed=987654321; for(int i=0;i<MAXN;i++) rnd[i]=splitmix(&seed); /* not forced odd: sum_r v[r] is fixed per row-sum class, odd multipliers would freeze the low bit */
    /* H and its orbits; pair up O and -O as orbit ids 2i, 2i+1 */
    char inH[MAXN]={0}; int ordH=0; { int st[MAXN],sp=0; st[sp++]=1; inH[1]=1;
        while(sp){int u=st[--sp]; ordH++; for(int g=0;g<ng;g++){int w=(int)((long)u*gens[g]%n); if(!inH[w]){inH[w]=1;st[sp++]=w;}}} }
    if(inH[n-1]){printf("n=%d: -1 lies in H, no skew block\n",n);return 1;}
    for(int j=0;j<n;j++) oid[j]=-1;
    K=0;
    for(int j=1;j<n;j++){ if(oid[j]>=0) continue;
        for(int h=1;h<n;h++) if(inH[h]) oid[(int)((long)j*h%n)]=K;
        if(oid[n-j]==K){printf("n=%d: an orbit equals its negative\n",n);return 1;}
        for(int h=1;h<n;h++) if(inH[h]) oid[(int)((long)(n-j)*h%n)]=K+1;
        K+=2; }
    if(K>30){printf("n=%d |H|=%d: K=%d orbits, too many\n",n,ordH,K);return 1;}
    /* shift classes under <H,-1> */
    for(int j=0;j<n;j++) cls[j]=-1;
    m=0; for(int j=1;j<n;j++){ if(cls[j]>=0) continue; rep[m]=j;
        for(int h=1;h<n;h++) if(inH[h]){int w=(int)((long)j*h%n); cls[w]=m; cls[n-w]=m;} m++; }
    for(int k=0;k<m;k++) for(int r=0;r<m;r++){ double c=0; for(int s=1;s<n;s++) if(cls[s]==r) c+=cos(2*M_PI*(double)((long)rep[k]*s%n)/n); Cc[k][r]=c; }
    target=0; for(int r=0;r<m;r++) target+=rnd[r]*(uint64_t)(int64_t)(-n);
    printf("n=%d |H|=%d orbits K=%d shift classes m=%d: A has 2^%d candidates, B,C,D 2^%d each\n",n,ordH,K,m,K/2,K); fflush(stdout);
    clock_t t0=clock();
    /* candidates */
    list_t A={0}; static list_t S[MAXN]; signed char x[MAXN]; int v[MAXN];
    for(uint32_t b=0;b<(1u<<(K/2));b++){ uint32_t mask=0; for(int i=0;i<K/2;i++) mask|=((b>>i)&1)?(1u<<(2*i)):(1u<<(2*i+1));
        expand(mask,x);
        if(aonly){ int same=1; for(int j=0;j<n;j++) if((x[j]>0?'+':'-')!=aonly[j]) same=0; if(!same) continue; }
        pafvec(x,v); if(!psd_ok(v,4.0*n)) continue; push(&A,mask,hashv(v)); }
    if(aonly) printf("AONLY set: the skew block is restricted to the one given, %zu candidate kept (validation mode, not a full search)\n",A.cnt);
    size_t raw[MAXN]={0};
    for(uint64_t b=0;b<((uint64_t)1<<K);b++){ expand((uint32_t)b,x); int rs=0; for(int j=0;j<n;j++) rs+=x[j]; int ar=abs(rs);
        raw[ar]++;
        int ok=0; long rem=4L*n-1-(long)ar*ar; if(rem>=2){ for(int c=1;(long)c*c<=rem&&!ok;c+=2){ long r2=rem-(long)c*c; int d=(int)lround(sqrt((double)r2)); if(d>0&&(long)d*d==r2&&(d&1)) ok=1; } }
        if(!ok) continue;
        pafvec(x,v); if(!psd_ok(v,4.0*n-1)) continue; push(&S[ar],(uint32_t)b,hashv(v)); }
    printf("skew A after PSD filter: %zu of %u\n",A.cnt,1u<<(K/2));
    printf("|row sum| : all H-invariant blocks with x[0]=+1 : kept after row-sum and PSD filter\n");
    for(int r=1;r<=n;r+=2) if(raw[r]) printf("  %3d : %zu : %zu\n",r,raw[r],S[r].cnt);
    printf("candidate generation %.1fs\n",(double)(clock()-t0)/CLOCKS_PER_SEC); fflush(stdout);
    long found=0; int ndec=0, skipped=0;
    for(int p=1;p<=n;p+=2) for(int q2=p;q2<=n;q2+=2){ long r2=4L*n-1-(long)p*p-(long)q2*q2; if(r2<(long)q2*q2) continue;
        int r=(int)lround(sqrt((double)r2)); if((long)r*r!=r2||!(r&1)||r>n) continue;
        int tri[3]={p,q2,r}; ndec++; if(stopped) break;
        if(!S[p].cnt||!S[q2].cnt||!S[r].cnt){ printf("row sums (1,%d,%d,%d): a class is empty, no solutions\n",p,q2,r); continue; }
        /* choose which value is B's */
        int best=-1; double bw=0,bL=0,bR=0;
        for(int i=0;i<3;i++){ int c=tri[(i+1)%3],d=tri[(i+2)%3]; double L=(double)A.cnt*S[tri[i]].cnt, R=(double)S[c].cnt*S[d].cnt/(c==d?2:1);
            if(best<0||L+R<bw){best=i;bw=L+R;bL=L;bR=R;} }
        int bv=tri[best],cv=tri[(best+1)%3],dv=tri[(best+2)%3];
        printf("row sums (1,%d,%d,%d): B class %d; table (A,B) pairs %.3g, probing (C,D) pairs %.3g\n",p,q2,r,bv,bL,bR); fflush(stdout);
        if(bL+bR>maxpairs){ printf("  SKIPPED (above maxpairs %.3g): not searched\n",maxpairs); skipped++; continue; }
        if(bL==0||bR==0) continue;
        int q=0; while(bL/(double)((size_t)1<<q)>4.0e6) q++;
        { size_t mn=S[bv].cnt<S[dv].cnt?S[bv].cnt:S[dv].cnt; while(q>0&&((size_t)1<<q)*8>mn) q--; }
        size_t P=(size_t)1<<q, msk=P-1;
        bucket(&S[bv],q); if(dv!=bv) bucket(&S[dv],q); if(cv!=bv&&cv!=dv) bucket(&S[cv],q);
        list_t *LB=&S[bv],*LC=&S[cv],*LD=&S[dv];
        size_t tcap=1; while(tcap<(size_t)(4.0*bL/P)+1024) tcap<<=1;
        uint64_t *tk=malloc(tcap*8), *tv=malloc(tcap*8);
        if(!tk||!tv){printf("  out of memory\n");return 3;}
        clock_t t1=clock(); long hits=0;
        for(size_t pp=0;pp<P&&!stopped;pp++){
            memset(tv,0xff,tcap*8); size_t ins=0;
            for(size_t i=0;i<A.cnt;i++){ size_t need=(size_t)((0-(uint64_t)pp-A.h[i])&msk);
                for(size_t j=LB->bst[need];j<LB->bst[need+1];j++){ uint64_t key=A.h[i]+LB->h[j]; size_t s=(size_t)((key>>q)*0x9e3779b97f4a7c15ULL>>20)&(tcap-1);
                    while(tv[s]!=~(uint64_t)0) s=(s+1)&(tcap-1);
                    tk[s]=key; tv[s]=((uint64_t)i<<32)|j; ins++; if(ins*2>tcap){printf("  table overflow\n");return 3;} } }
            #pragma omp parallel for schedule(dynamic,64) reduction(+:hits)
            for(size_t c=0;c<LC->cnt;c++){ if(stopped) continue; size_t need=(size_t)(((uint64_t)pp+target-LC->h[c])&msk);
                size_t lo=LD->bst[need], hi=LD->bst[need+1];
                if(LC==LD&&lo<c) lo=c;
                for(size_t d=lo;d<hi;d++){ uint64_t key=target-(LC->h[c]+LD->h[d]); size_t s=(size_t)((key>>q)*0x9e3779b97f4a7c15ULL>>20)&(tcap-1);
                    while(tv[s]!=~(uint64_t)0){ if(tk[s]==key){ hits++;
                            #pragma omp critical
                            { if(!stopped&&verify(A.mask[tv[s]>>32],LB->mask[tv[s]&0xffffffffu],LC->mask[c],LD->mask[d],out,found)){ found++; if(found>=stopat) stopped=1; } }
                        } s=(s+1)&(tcap-1); } } }
        }
        free(tk); free(tv);
        printf("  passes %zu, hash hits %ld, verified solutions so far %ld, cpu %.1fs\n",P,hits,found,(double)(clock()-t1)/CLOCKS_PER_SEC); fflush(stdout);
    }
    if(stopped){ printf("RESULT n=%d |H|=%d K=%d solutions>=%ld STOPPED EARLY at the solution cap, count is a lower bound\n",n,ordH,K,found); return 0; }
    if(!ndec) printf("no odd b,c,d with 1+b^2+c^2+d^2=%d\n",4*n);
    printf("RESULT n=%d |H|=%d K=%d solutions=%ld skipped_decompositions=%d\n",n,ordH,K,found,skipped);
    fclose(out); return 0;
}
